/** Machine translated draft; religious and linguistic review pending. */
internal object DuaDoiDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("तेरी दया दी में आशा करदा आं", "ऐ अल्लाह, तेरी दया दी ही में आशा करदा आं, इस करियै मिगी इक पलक झपकने तक्कर अपने पर नेईं छडो ते मेरे सारे मामलें गी ठीक करो। तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ।", "दुखी दी दुआ (दावत अल-मक्रूब)।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इसगी दुखी दी दुआ आखेआ।"),
        "dua_against_enemy_ahzab" to DuaText("दुश्मन दी सैनाएं दे खलाफ", "ऐ अल्लाह, किताब दा खुलासा करने आह्ला! गिनती च तेजी लाओ! संघें गी तोड़ो। ऐ अल्लाह, उʼनें गी तोड़ो ते हिलाओ।", "दुश्मनै दे खलाफ-संघ दी लड़ाई दा दुआ।", "दुश्मन दे खलाफ पैगंबर दी सल्लाही अल-ए-अल-ए-अल-ए-अ-स-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ-अ -"),
        "dua_anta_adudi" to DuaText("तुस मेरे मददगार ओ।", "ऐ अल्लाह, तुस मेरे सहारा ते मेरे मददगार ओ। में तुंʼदे राहें योजना बनाउंदा आं, तुंʼदे राहें अग्गें बधदा आं ते तुंʼदे राहें लड़दा आं।", "कुसै मकाबले जां बड्डी चुनौती शा पैह्लें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने जुद्ध च एह् आखेआ हा।"),
        "dua_ikfinihim" to DuaText("उंʼदे खलाफ मेरे लेई काफी ऐ", "ऐ अल्लाह, उंʼदे खलाफ तुस जिʼयां बी करी सकदे ओ, मेरे लेई काफी ऐ।", "उत्पीड़कें दी बुराई दे खलाफ-द पीपल ऑफ द डिच दी कहाणी च लड़के दी दुआ।", "अल्लाह ने लड़के गी जुल्म करने आह्ले लोकें शा बचाया।"),
        "dua_qadarullah" to DuaText("जिसलै किश बुरा होंदा ऐ", "एह् अल्लाह दा हुकम ऐ, ते उʼनें ओह् कीता जेह्ड़ा ओह् करना चाह्न्नां।", "जिसलै किश अप्रिय होंदा ऐ, तां'सिर्फ तां'कहने दे बजाए।", "'अगर छड़ा'शैतान दा दरवाज़ा खोलदा ऐ।"),
        "dua_ala_kulli_hal" to DuaText("हर दशा च सराह्ना करो", "हर दशा च सारी स्तुति अल्लाह आस्तै ऐ।", "जिसलै किश नापसंद होंदा ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् किश नापसंद दा सामना करने पर आखेआ।"),
        "dua_dogs_barking" to DuaText("राती कुत्तरें गी भौंकने दी आवाज़ सुनाई दिंदी ऐ", "में शापित शयतान शा अल्लाह दी शरण मंगदा आं।", "कुत्तरें दी भौंकने जां गदहे दी आवाज़ सुनने पर राती च गांड दा बʼरा निकलदा ऐ।", "ओह् ओह् दिक्खेआ करदे न जेह्ड़ा तुस नेईं दिक्खेआ करदे।"),
        "dua_leaving_home_adilla" to DuaText("भटकने शा शरण", "हे अल्लाह, में तुंʼदे शा शरण लैंदा आं जे में पथराव नेईं करां जां पथराव च जाई सकनां, नेईं तां में पथराव जां पथराव च जाई सकनां, नेईं तां में पथराव करां जां पथराव च पाई जाई सकनां, नेईं तां में पथराव करां जां मेरे कन्नै अन्याय कीता जाई सकां, नेईं तां में मूर्खता कन्नै बर्त-बरात करां जां मेरे कन्नै मूर्खतापूर्ण बर्त-बरात कीती जाई सकां।", "घर थमां बाह्र निकलदे समें-उम्म सलाम (र) आसेआ सुनाया गेआ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम जिसलै बी अपने घर थमां बाह्र निकलदे हे तां एह् पाठ करदे हे।"),
        "dua_ascending_descending" to DuaText("उप्पर जाना ते खʼल्ल जाना", "अल्लाह सभनें शा महान ऐ (जिसलै उप्पर जंदा ऐ)।-महिमावान ऐ अल्लाह।", "यात्रा च उप्पर जंदे समें'अल्लाहू अकबर'ते खʼल्लदे समें'सुभानल्लाह'आखिये।", "यात्रा करदे समें साथी (आर. ए.) दा अभ्यास।"),
        "dua_traveller_sahar" to DuaText("भोर होने शा पैह्लें यात्री दी दुआ", "इक श्रोता ने ख़ुदा दी साडी तसबीह ते उस दी हम पर बरकत सुनी ऐ। ऐ हमारे रब, साडे कन्नै चल ते हम पर अपनी बरकत करा-(में एह् आखना ऐ) ख़ुदा दी आग थमां पनाह लैने आस्तै।", "इक जातरा च, भ्यागा होने शा पैह्लें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् यात्रा करदे समें भ्यागा होने शा पैह्लें आखेआ हा।"),
        "dua_zawwadakallah" to DuaText("यात्री गीः अल्लाह तक्वा प्रदान करे", "अल्लाह तुसें गी तुंʼदी जातरा आस्तै तक्वा प्रदान करे, तुंʼदे पापें गी माफ करे ते तुस जित्थै बी होई जाओ, तुंʼदे आस्तै भलाई गी सौखा करे।", "जिसलै कुसै यात्री गी विदाई दित्ती जंदी ऐ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने कुसै यात्राकरत गी एह् दुआ दित्ती।"),
        "dua_traveller_to_resident" to DuaText("पिट्ठें रहने आह्ले लोकें आस्तै यात्री", "में तुसें गी अल्लाह गी सौंपी दिंदा आं, जिंʼदे पर भरोसा कदें नेईं गुजरी जंदा।", "परोआर गी विदाई दिंदे होई यात्री ने आखेआ।", "परोआर दी सुरक्षा अल्लाह गी सौंपी देओ।"),
        "dua_entering_village" to DuaText("कुसै शैह्र जां ग्रां च दाखल होना", "ऐ अल्लाह, सत्तें आसमानें दा ते उंʼदी हर इक छांव दा, सत्तें धरतीएं दा ते उंʼदे सारे लहराएं दा, शैतानें दा ते उंʼदे सारे गुमराह करने आह्ले दा, रब, बवंडरें दा ते हर इक चीज दा, जेह्ड़ा ओह् बिखेरदे न, रब! असीं तुंʼदे शा इस शैह्र दी भलाई ते ओह्दे लोकें दी भलाई दी मंग करदे आं, ते असीं तुंʼदे च एह्दे बुरे, एह्दे लोकें दी बुराई ते एह्दे च जे बुराई ऐ ओह्दे शा पनाह लैंदे आं।", "कुसै शैह्र जां शैह्र च दाखल होने शा पैह्लें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम जिसलै बी कुसै शैह्र च दाखल होना चाह्ंदे हे तां एह् पाठ करदे हे।"),
        "dua_vehicle_stumbles" to DuaText("जिसलै वाहन डिग्गदा ऐ", "अल्लाह दे नांऽ पर।", "जिसलै माउंट जां वाहन फिसलदा ऐ जां डिग्गदा ऐ, तां'शैतन मरी जाई सकदा ऐ'कहने दे बजाए।", "बिस्मिल्लाह कहने कन्नै शैतान इक मक्खी दे आकार तक्कर सिकुड़ जंदा ऐ।"),
        "dua_ajz_kasal_haram" to DuaText("कमजोरी ते बुढापे शा शरण", "हे अल्लाह, में तेरे च असहायता ते आलस्य, कायरता ते बुढापे, जीवन ते मौत दी अज़माइशें ते क़ब्र दी सʼजा शा पनाह लैंदा आं।", "शरण दी इक व्यापक दैनिक दुआ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अक्सर दुआ कीती।"),
        "dua_sharri_ma_amiltu" to DuaText("मेरे बुरे कम्में शा शरण लो", "हे अल्लाह, में जेह्ड़ा कीता ऐ ओह्दे बुरे शा ते जेह्ड़ा नेईं कीता ऐ ओह्दे बुरे शा तुंʼदी शरण लैंदा आं।", "आयशा (र.) दे मताबक पैगंबर सल्लल्लाहु अलैहि वसल्लम दी दुआ।", "केह् कीता गेआ ते केह् पूर्ववत करी दित्ता गेआ, दौनें दे नतीजें शा सुरक्षा।"),
        "dua_jahdil_bala" to DuaText("गंभीर परखें शा शरणार्थ", "हे अल्लाह, में तुंʼदे च गंभीर परख, दुख, बुरे हुकम ते दुश्मनें दे गर्व कन्नै बचने आस्तै शरण मंगदा आं।", "गंभीर परखें ते दुश्मनें दे हौसले-हौसले शा शरण।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इʼनें चार चीजें थमां पनाह लेई।"),
        "dua_fitnat_ghina_faqr" to DuaText("धन ते गरीबी दे परखें शा शरण", "हे अल्लाह, में तेरे च आलस्य ते बुढापे, पाप ते कर्जे, क़ब्र दे मुक़दमे ते सʼजा, अग्ग दे मुक़दमे ते सʼजा, धन दे मुक़दमे दी बुराई ते गरीबी दे मुक़दमे शा पनाह मंगदा आं।", "कब्र, नर्क, धन ते गरीबी (दुआ दा हिस्सा) दे अज़माइशें शा शरण।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम थमां शरण दी इक व्यापक दुआ।"),
        "dua_kufr_faqr" to DuaText("अविश्वास ते गरीबी शा शरण", "ऐ अल्लाह, में तेरे च अविश्वास ते गरीबी थमां पनाह लैंदा आं, ते मैं तेरे च कब्र दी सʼजा शा पनाह लैंदा आं। तेरे बगैर कोई पूज्य-प्रभु नेईं ऐ।", "त्रै बारी भ्यागा ते सʼञै।", "अबू बकर (र) ने पैगंबर सल्लल्लाहु अलैहि वसल्लम गी एह् आखदे सुणिआ।"),
        "dua_sharri_sami" to DuaText("मेरी संवेदनाएं दी बुराई शा शरण लो", "हे अल्लाह, में अपनी सुन्ने दी बुराई, अपनी नज़र दी बुराई, अपनी जीभ दी बुराई, अपने दिल दी बुराई ते अपनी इच्छा दी बुराई शा तुंʼदे च शरण मंगदा आं।", "शकल इब्न हुमायद (र.) गी सिखाया गेआ।", "अंगें ते अपने आप गी पाप कोला बचाने आस्तै इक दुआ।"),
        "dua_hadm_gharaq" to DuaText("अचानक मौत ते हादसें शा शरण", "हे अल्लाह, में तुंʼदे च कुचले जाने (इक इमारत आसेआ), उचाई शा डिग्गने, डुब्बी जाने, जलने ते बुढापे शा, मौत दे समें मुझे पथभ्रष्ट करने आह्ले शैतान शा, अपने रस्ते शा भगोड़ने दे दुरान मरने ते (ज़हरीले) डंक कन्नै मरने शा पनाह लैंदा आं।", "हादसें ते बुरी मौत शा शरण।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम थमां इक शरण दी दुआ।"),
        "dua_ju_khiyanah" to DuaText("भुखमरी ते विश्वासघात शा शरण", "हे अल्लाह, में तेरी भुखमरी शा पनाह लैंदा आं, की जे ओह् इक भैड़ा साथी ऐ, ते में तेरे कन्नै विश्वासघात शा पनाह लैंदा आं, की जे ओह् इक भैड़ा विश्वास करने आह्ला ऐ।", "भुखमरी ते विश्वासघात शा शरण।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम थमां इक शरण दी दुआ।"),
        "dua_huda_tuqa" to DuaText("मार्गदर्शन, धर्मनिष्ठा, शुद्धता ते पर्याप्तता", "हे अल्लाह, में तुंʼदे शा मार्गदर्शन, धर्मनिष्ठा, सतीता ते आत्मनिर्भरता दी मंग करदा आं।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दी इक छोटी, व्यापक दुआ।", "धर्म ते इस दुनिया दे चार मूलभूत आशीर्वाद।"),
        "dua_aslih_li_dini" to DuaText("मेरे धर्म, दुनिया ते बाद दे धर्म गी ठीक करो।", "हे अल्लाह, मेरे धर्म गी ठीक करो, जेह्ड़ा मेरे सारे मामलें दी सुरक्षा ऐ; मेरे सांसारिक जीवन गी ठीक करो, जेह्दे च मेरी रोजी-रोटी ऐ; ते अपने आख़िरत गी ठीक करो, जेह्दे पर मैं बापस जाईंगा। मेरे आस्तै हर भले च जीवन गी बधावा बनाओ, ते मेरे लेई मौत गी हर बुराई थमां राहत देओ।", "धर्म च सधार, इस दुनिया ते आख़िरत-त्र'ऊं।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दी इक व्यापक दुआ।"),
        "dua_musarrifal_qulub" to DuaText("अपने आज्ञा पालन आस्तै अपना दिल बदलो", "हे अल्लाह, दिलें दे मोड़ने आह्ले, तुंʼदी आज्ञा पालन आस्तै असां दा दिल मोड़ो।", "दिल गी आज्ञा पालन च द्रिढ़ रखने आस्तै इक दुआ।", "सभनें लोकें दे दिल परम दयावान दी द'ऊं उंगलियें दे बिच्च न।"),
        "dua_jannah_nar" to DuaText("जन्नाह्, अग्ग शा शरण मंगना", "हे अल्लाह, में तुंʼदे शा जन्नत मंगदा आं ते मैं तुंʼदे च अग्ग शा पनाह लैंदा आं।", "ताशाहुद दे परैंत्त जां कुसै बी समें।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआः साʼदियां दुआयां बी एह्दे आस्सै-पास्सै घुरदियां न।"),
        "dua_khayri_kullih" to DuaText("हून ते बाद च सभनें दा ठीक ऐ।", "ऐ अल्लाह, में तुंʼदे शा सारे भले आस्तै मंगदा आं-फौरन ते देरी कन्नै, जेह्ड़ा में जानदी आं ते जेह्ड़ा में नेईं जानदी-ते में तुंʼदे च हर बुराई थमां पनाह मंगदी आं-फौरन ते देरी कन्नै, जेह्ड़ा में जानदी आं ते जेह्ड़ा में नेईं जानदी। हे अल्लाह, में तुंʼदे शा जन्नत दी मन्नत करदा आं ते जेह्ड़ा किश शब्द ते कर्म मिगी ओह्दे कोल लेई जंदे न, ते में तुंʼदे च अग्ग कोला पनाह मंगदा आं ते जेह्ड़ा किश शब्द ते कर्म मिगी ओह्दे कोल लेई जंदे न।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आयशा (रा.) (दुआ दा हिस्सा) गी एह् व्यापक दुआ सिखाई।", "इक दुआ जेह्ड़ी हर भले गी इकट्ठी करदी ऐ।"),
        "dua_ihdini_saddidni" to DuaText("मेरा मार्गदर्शन करो ते मिगी सही बनाओ", "हे अल्लाह, मेरा मार्गदर्शन करो ते मिगी सही रस्ते पर चलांदे रहो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् अली (र) गी सिखाया हा।", "मार्गदर्शन गी सिड़क पर मार्गदर्शन दे रूपा च सोच्नो, ते सादद गी तीर दी सीधीता दे रूपा च सोच्नो।"),
        "dua_hubbaka" to DuaText("अल्लाह शा प्यार मंगना।", "हे अल्लाह, में तुंʼदा प्यार, तुंʼदे प्यार करने आह्ले लोकें दा प्यार ते तुंʼदे प्यार च औने आह्ले कम्में आस्तै तुंʼदी विनती करदा आं। हे अल्लाह, अपने प्यार गी मेरे लेई, मेरे परोआर ते ठंडे पानी कोला मते प्यार करो।", "पैगंबर सल्लल्लाह् अलैहि वसल्लम आसेआ दाऊद (अ. स.) दी दुआ कन्नै सरबंधत ऐ।", "अल्लाह दा प्यार सभनें शा बड्डी दौलत ऐ।"),
        "dua_filal_khayrat" to DuaText("चंगा करना ते बुराई छोड़ना", "हे अल्लाह, में तुंʼदे शा मंगदा आं जे में भले कम्म करूं, बुरे कम्म छोड़ी देवां ते गरीबें कन्नै प्यार करां, ते तुस मिगी माफ करी देओ ते मुझ पर दया करो। ते जिसलै तुस कुसै जाति आस्तै परख दा इरादा करदे ओ, तां मिगी बगैर परख दे लेई जाओ। में तुंʼदा प्यार, अपने प्यार करने आह्ले लोकें दा प्यार ते अपने प्यार दे करीब लाने आह्ले कम्में दा प्यार मंगदा आं।", "अल्लाह ने पैगंबर सल्लल्लाह् अलैहि वसल्लम गी एह् दुआ सपने च सिखाई।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआः एह् सच ऐ, इस करियै इसगी सिखो ते सिखाओ।"),
        "dua_bi_ilmikal_ghayb" to DuaText("मिगी जिʼयां जीने देओ, जिʼयां तक्कर जीवन चंगा ऐ।", "हे अल्लाह, अपने अनदेखे दे ज्ञान ते सृष्टी पर अपनी शक्ति कन्नै-जिसलै तक्कर तुस जानदे ओ जे जीवन मेरे लेई चंगा ऐ, उसलै तक्कर मिगी जीवित र'व, ते जिसलै तुस जानोगे जे मौत मेरे लेई चंगा ऐ तां मिगी लेई जाओ। हे अल्लाह, में तुंʼदे शा निजी ते सार्वजनक रूप च डरने दी, संतुष्टि ते क्रोध च सच्चाई दे वचन आस्तै, ते गरीबी ते धन च संयम आस्तै विनती करदा आं।", "अम्मार इब्न यासिर (आर. ए.) (शुरुआती हिस्सा) दी नमाज़ दुआ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् दुआ दुआ च कीती।"),
        "dua_ism_azam_mannan" to DuaText("इस्मे-ए-आज़म-अल-मन्नान", "ऐ अल्लाह, में तुंʼदे शा विनती करदा आं, की जे सारी स्तुति तुंʼदे लेई ऐ, तुंʼदे अलावा कोई पूज्य-प्रभु नेईं ऐ, जेह्ड़ा कृपा प्रदान करदा ऐ, आसमानें ते धरती दा निर्माता ऐ। ऐ महानता ते सम्मान दे स्वामी, ऐ सदा-जीवित, ऐ पालनकर्ता!", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआ जे इस मनुष्या ने अल्लाह दे महानतम नांऽ कन्नै दुआ बनाई।", "इस नांऽ कन्नै बने दे दुआ दा जवाब दित्ता जंदा ऐ।"),
        "dua_ism_azam_ahad_samad" to DuaText("इस्मे-ए-आज़म-अल-अहद अस-समद", "हे अल्लाह, में तुंʼदे शा विनती करदा आं, की जे में गवाही दिंदा आं जे तुस अल्लाह ओ; तुंʼदे अलावा कोई पूज्य-प्रभु नेईं ऐ, इक, आत्मनिर्भर, जेह्ड़ा ना पैदा होंदा ऐ ते ना गै पैदा होंदा ऐ, ते ओह्दे कन्नै कोई तुलना नेईं कीती जाई सकदी।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने आखेआ जे इस आदमी ने अल्लाह शा उंʼदे महानतम नांऽ कन्नै माँगा हा।", "जिसलै एह्दे द्वारा पुछी जंदी ऐ, तां ओह् दिंदे न; जिसलै एह्दे द्वारा बुलाए जंदे न, तां ओह् जवाब दिंदे न।"),
        "dua_thabbitni_hadiyan" to DuaText("मिगी द्रिढ़, हिदायतकारी आह्ला ते मार्गदर्शक बनाओ", "हे अल्लाह, मिगी द्रिढ़ बनाओ ते मिगी मार्गनिर्देशन करने आह्ला ते मार्गनिर्देशन पाने आह्ला बनाओ।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने इस दुआ गी जरीर (रा) (अपने लेई'थाबितनी'आखदे न) आस्तै बनाया।", "जरीर (आर. ए.) आस्तै मूल दुआ च'थब्बित-हु'शब्दें दा इस्तेमाल कीता गेआ ऐ।"),
        "dua_rabbighfir_tub_alayya" to DuaText("मिगी माफ करी देओ ते मेरा पश्चाताप मंजूर करो।", "ऐ मेरे रब, मिगी माफ करी देओ ते मेरा पश्चाताप मंजूर करो। तुस तोह्फ करने आह्ले, दयावान ओ।", "इक गै बैठक च सौ बारी-पैगंबर सल्लल्लाह् अलैहि वसल्लम दा अभ्यास।", "साथीएं पैगंबर सल्लल्लाह् अलैहि वसल्लम गी इक बैठक च सौ बारी आखने दी गिनती कीती।"),
        "dua_rafiq_ala" to DuaText("मरने आह्ले व्यक्ति दा दुआ", "हे अल्लाह, मिगी माफ करी देओ, मुझ पर दया करो ते मेरे कन्नै सर्वोच्च साथी दे कन्नै शामल होवो।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दी खीरली दुआ-बीमार व्यक्ति आस्तै अपने लेई आखना।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने अपने गुज़रने दे समें एह् दुआ कीती ही।"),
        "dua_la_bas_tahur" to DuaText("बीमारें गी दिलासा देनाः शुध्दीकरण", "कोई नुकसान नेईं; जे अल्लाह चाहे तां एह् इक शुध्दीकरण (पापें शा) ऐ।", "दौरा करदे समें बीमारें गी दिलासा देना।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने एह् बात बीमारें कन्नै मिलने दे दुरान आखी ही।"),
        "dua_talqeen" to DuaText("मरने आस्तै तलकीन", "अल्लाह दे अलावा कुसै गी बी पूजा करने दा अधिकार नेईं ऐ।", "मरदे होई कुसै व्यक्ति दे कोल कलिमा दा पाठ करो (उʼनें गी एह् कहने आस्तै मजबूर नेईं करो)।", "जेह्ड़ा बी आखरी शब्द'ला इलाहा इल्लल्लाह'ऐ, ओह् स्वर्ग च दाखल होग (अबू दाऊद 3116)।"),
        "dua_ahyini_ma_kanat" to DuaText("मौत दी कामना करने दे बजाए", "हे अल्लाह, जिसलै तक्कर मेरे लेई जीवन चंगा ऐ, उसलै तक्कर मिगी जिʼंदा रक्खेआ करो, ते जिसलै मेरे लेई मौत चंगा होग तां मिगी लेई जाओ।", "औकड़ च मौत दी कामना करने दे बजाए।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम ने मौत दी कामना करने पर रोक लाई ते एह्दे बजाए एह् सिखाया।"),
        "dua_for_one_i_cursed" to DuaText("कुसै आस्तै में शब्दें कन्नै दुखांदा आं", "ऐ अल्लाह, जिस बी विश्वासी दा में अपमान कीता ऐ, उसी क़ियामत दे दिन अपने आस्तै अपने नेड़ता दा साधन बनाओ।", "कुसै दे लेई जेह्दे कन्नै तुस गुस्से च बुरी गल्ल कीती ही।", "पैगंबर सल्लल्लाहु अलैहि वसल्लम दा इक दुआ।"),
    )
}
